a(209,'<ffx:wonder_light>أتعلم يا أرتيوم... <ffx:smile_light>أتأمل ستيبان وكاتيا، وأتأمل حالنا أنا وأنت... <ffx:smile>وأفكر كم نحن محظوظون! <ffx:sadness_light>كان الأمر مختلفًا تمامًا بين أبي وأمي... <ffx:sadness>كان سيئًا...<ffx:neutral>')
a(211,'<ffx:sadness_light>بالطبع لم أخبرك... <ffx:sadness>كان السبب أبي. <ffx:sadness_strong>كان أشد قسوة آنذاك. يعود من الثكنة <ffx:disgust>ويتناول زجاجة الخمر قبل أن ينتهي من خلع حذائه... <ffx:sadness>يتشاجران، <ffx:anger_light>ثم يغيب عن البيت فترة...<ffx:neutral>')
a(212,'<ffx:wonder>وأثناء غيابه، <ffx:sadness>كانت تشرب هي أيضًا... <ffx:sadness_strong>وحين تفيق، تبكي. <ffx:wonder_light>كان الشراب يريحها، فتستغرق في أحلامها حين تسكر...<ffx:neutral>','Sober هنا الإفاقة من السكر لا الرصانة الخلقية؛ الزمن تكراري ماض.')
a(214,'<ffx:sadness_light>كنت في الخامسة آنذاك، ولم أكن أفهم الكثير... <ffx:wonder_light>لكنني كنت أتخيل القرية والمحيط بوضوح شديد... <ffx:sadness>لأنني كنت أصدقها.<ffx:neutral>')
a(216,'<ffx:sadness>كفّ أبي عن الشرب بعد موت أمي... <ffx:wonder>لم يكن يهتم بي كثيرًا من قبل، <ffx:wonder_strong>لكن بعد رحيلها <ffx:wonder_light>لم يعد يتركني وحدي، <ffx:smile_light>وكان يصطحبني إلى كل مكان... <ffx:sadness>ومع ذلك لم نتحدث عنها إلا مرتين تقريبًا...<ffx:neutral>')
a(217,'<ffx:wonder_light>كانت لدي دمية اسمها جانا. <ffx:smile_light>كنت أتخيل أنها ابنتي <ffx:wonder_light>وأننا نذهب إلى المحيط معًا... <ffx:sadness>ثم أخفاها أبي... وقال إنها ضاعت. <ffx:wonder_light>لعله لم يرد أن يعذبني التفكير في حلم أمي...<ffx:neutral>')
a(220,'<ffx:wonder>بالمناسبة، لطالما <ffx:sadness_light>تساءلت: بم يحلم أبي؟ <ffx:anger_light>لا بد أن له أحلامًا، <ffx:wonder>فما هي؟ رتبة أعلى؟ <ffx:sadness>إنه يستطيع اختيار أي رتبة...<ffx:neutral>')
a(221,'<ffx:wonder>إنقاذ الناس؟ وماذا سيفعل من ينقذهم <ffx:sadness>بعد ذلك؟ يظلون تحت الأرض؟ لم أفهمه قط... <ffx:wonder>ما الذي يرجوه من الحياة؟ وما الذي يسعده؟<ffx:neutral>')
a(222,'<ffx:sadness>لعله لا يرجو شيئًا... <ffx:sadness_strong>لم يجد وقتًا يفكر فيه بالغد. <ffx:disgust>تحت الأرض، في المترو، لا تخطر مثل هذه الأفكار ببالك بسهولة... <ffx:wonder>أما هنا، على السطح...<ffx:neutral>')
a(223,'<ffx:smile>أما أنا فأعرف ما أريد فعله! <ffx:wonder>أريد أن أجري على الرمال حافية القدمين، <ffx:sadness_light>وأن أبني قلعة رملية لأطفالنا... <ffx:wonder_light>أتخيل طفلين: صبيًا وفتاة. <ffx:smile>سيشبهك الصبي تمامًا... <ffx:smile_light>وسنسبح والجبال خلفنا!<ffx:neutral>')
a(224,'<ffx:smile_light>بيوت خشبية على الشاطئ... <ffx:wonder_light>ستوقظنا الشمس كل يوم وهي تشرق من المحيط... <ffx:anger_light>ذلك المرفأ هو وجهتنا. <ffx:smile_light>وهو يستحق أن نذهب إليه، حتى لو اضطررنا إلى عبور نصف العالم...<ffx:neutral>')
a(225,'<ffx:sadness_light>لا بد لكل إنسان من وجهة... <ffx:wonder_light>نقطة على الخريطة يطمح إلى بلوغها، حيث يمكنه أخيرًا أن يسعد. <ffx:smile_light>لكل رفيق من رفاقنا وجهته...<ffx:neutral>')
